def has_cycle_undirected(g):
    visited = [False] * len(g)
    def dfs(u, parent):
        visited[u] = True
        for v in g[u]:
            if not visited[v]:
                if dfs(v, u):
                    return True
            elif v != parent:
                return True
        return False
    for u in range(len(g)):
        if not visited[u] and dfs(u, -1):
            return True
    return False

def has_cycle_directed(g):
    WHITE, GRAY, BLACK = 0, 1, 2
    state = [WHITE] * len(g)
    def dfs(u):
        state[u] = GRAY
        for v in g[u]:
            if state[v] == GRAY:
                return True
            if state[v] == WHITE and dfs(v):
                return True
        state[u] = BLACK
        return False
    return any(dfs(u) for u in range(len(g)) if state[u] == WHITE)

