def eval_expr(s):
    stack, num, sign = [], 0, 1
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch in '+-':
            stack.append(sign * num)
            num, sign = 0, 1 if ch == '+' else -1
    stack.append(sign * num)
    return sum(stack)

